/**
 * Validates JSON input from stdin.
 *
 * Usage: echo '{"key": "value"}' | bun run src/validate-json.ts
 * Exit code 0 for valid JSON, 1 for invalid.
 */

export interface ValidationResult {
  valid: boolean;
  error?: string;
}

/**
 * Validate a string as JSON.
 */
export function validateJson(input: string): ValidationResult {
  if (input.trim().length === 0) {
    return { valid: false, error: "Empty input" };
  }

  try {
    JSON.parse(input);
    return { valid: true };
  } catch (err) {
    const message = err instanceof Error ? err.message : "Unknown parse error";
    return { valid: false, error: message };
  }
}

/**
 * Read stdin and validate as JSON.
 */
async function main(): Promise<void> {
  const input = await Bun.stdin.text();
  const result = validateJson(input);

  if (result.valid) {
    const parsed = JSON.parse(input);
    console.log(JSON.stringify(parsed, null, 2));
    process.exit(0);
  } else {
    console.error(`Invalid JSON: ${result.error}`);
    process.exit(1);
  }
}

main();

import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  test("validates a simple object", () => {
    const result = validateJson('{"key": "value"}');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("validates an array", () => {
    const result = validateJson('[1, 2, 3]');
    expect(result.valid).toBe(true);
  });

  test("validates a string primitive", () => {
    const result = validateJson('"hello"');
    expect(result.valid).toBe(true);
  });

  test("validates a number primitive", () => {
    const result = validateJson("42");
    expect(result.valid).toBe(true);
  });

  test("validates null", () => {
    const result = validateJson("null");
    expect(result.valid).toBe(true);
  });

  test("validates boolean", () => {
    const result = validateJson("true");
    expect(result.valid).toBe(true);
  });

  test("rejects malformed JSON", () => {
    const result = validateJson("{key: value}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("rejects empty input", () => {
    const result = validateJson("");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("rejects whitespace-only input", () => {
    const result = validateJson("   ");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("rejects trailing comma", () => {
    const result = validateJson('{"a": 1,}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("rejects incomplete JSON", () => {
    const result = validateJson('{"key":');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });
});

