describe("formatGreeting", () => {
  test("returns greeting with default prefix", () => {
    expect(formatGreeting("Alice")).toBe("Hi, Alice! Welcome!");
  });

  test("returns greeting with custom prefix", () => {
    expect(formatGreeting("Bob", "Hey")).toBe("Hey, Bob! Welcome!");
  });

  test("handles empty name", () => {
    expect(formatGreeting("")).toBe("Hi, ! Welcome!");
  });
});

