        "file_path": "/private/tmp/rp1-evals/98ce475e/workspace/src/json-validator.ts",
        "content": "/**\n * Ultra-performant JSON validation module.\n * Zero external dependencies — uses only Bun/TypeScript built-ins.\n */\n\n// ─── Types ───────────────────────────────────────────────────────────────────\n\nexport type JsonSchemaType = \"string\" | \"number\" | \"boolean\" | \"object\" | \"array\" | \"null\";\n\nexport interface JsonSchema {\n  type: JsonSchemaType;\n  /** For object types: property schemas */\n  properties?: Record<string, JsonSchema>;\n  /** For object types: required property names */\n  required?: string[];\n  /** For array types: schema for each item */\n  items?: JsonSchema;\n  /** Whether the value can be null in addition to its type */\n  nullable?: boolean;\n  /** For string types: minimum length */\n  minLength?: number;\n  /** For string types: maximum length */\n  maxLength?: number;\n  /** For number types: minimum value */\n  minimum?: number;\n  /** For number types: maximum value */\n  maximum?: number;\n  /** For array types: minimum items */\n  minItems?: number;\n  /** For array types: maximum items */\n  maxItems?: number;\n}\n\nexport interface ValidationError {\n  path: string;\n  message: string;\n  expected: string;\n  received: string;\n}\n\nexport interface ValidationResult {\n  success: boolean;\n  errors: ValidationError[];\n}\n\nexport interface ParseResult<T = unknown> {\n  success: boolean;\n  data?: T;\n  error?: string;\n}\n\n// ─── Fast JSON Check ─────────────────────────────────────────────────────────\n\n/**\n * Ultra-fast check if a string is valid JSON.\n * Uses try/catch with native JSON.parse — the fastest possible approach in JS\n * since JSON.parse is implemented in C++ in V8/JSC.\n */\nexport function isValidJson(input: string): boolean {\n  if (input.length === 0) return false;\n\n  // Fast early-exit: check first non-whitespace char\n  const firstChar = input.trimStart()[0];\n  if (\n    firstChar !== \"{\" &&\n    firstChar !== \"[\" &&\n    firstChar !== '\"' &&\n    firstChar !== \"t\" &&\n    firstChar !== \"f\" &&\n    firstChar !== \"n\" &&\n    (firstChar < \"0\" || firstChar > \"9\") &&\n    firstChar !== \"-\"\n  ) {\n    return false;\n  }\n\n  try {\n    JSON.parse(input);\n    return true;\n  } catch {\n    return false;\n  }\n}\n\n// ─── Safe Parse ──────────────────────────────────────────────────────────────\n\n/**\n * Safely parse JSON with a typed result.\n * Avoids throwing — returns a discriminated union instead.\n */\nexport function parseJsonSafe<T = unknown>(input: string): ParseResult<T> {\n  if (input.length === 0) {\n    return { success: false, error: \"Empty input\" };\n  }\n\n  try {\n    const data = JSON.parse(input) as T;\n    return { success: true, data };\n  } catch (e) {\n    return {\n      success: false,\n      error: e instanceof Error ? e.message : \"Invalid JSON\",\n    };\n  }\n}\n\n// ─── Schema Validation ───────────────────────────────────────────────────────\n\n/**\n * Validate a JSON string against a schema.\n * Parses once, then validates the parsed structure iteratively using a\n * work stack to avoid recursion overhead for deeply nested objects.\n */\nexport function validateJson(input: string, schema: JsonSchema): ValidationResult {\n  const errors: ValidationError[] = [];\n\n  // Step 1: Parse\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(input);\n  } catch (e) {\n    errors.push({\n      path: \"$\",\n      message: \"Invalid JSON\",\n      expected: \"valid JSON\",\n      received: e instanceof Error ? e.message : \"parse error\",\n    });\n    return { success: false, errors };\n  }\n\n  // Step 2: Validate iteratively using a work stack\n  const stack: Array<{ value: unknown; schema: JsonSchema; path: string }> = [\n    { value: parsed, schema, path: \"$\" },\n  ];\n\n  while (stack.length > 0) {\n    const item = stack.pop()!;\n    validateValue(item.value, item.schema, item.path, errors, stack);\n  }\n\n  return { success: errors.length === 0, errors };\n}\n\n/**\n * Validate a single value against a schema.\n * Pushes child validations onto the stack instead of recursing.\n */\nfunction validateValue(\n  value: unknown,\n  schema: JsonSchema,\n  path: string,\n  errors: ValidationError[],\n  stack: Array<{ value: unknown; schema: JsonSchema; path: string }>,\n): void {\n  // Handle null\n  if (value === null) {\n    if (schema.nullable || schema.type === \"null\") return;\n    errors.push({\n      path,\n      message: \"Expected non-null value\",\n      expected: schema.type,\n      received: \"null\",\n    });\n    return;\n  }\n\n  const actualType = getJsonType(value);\n\n  // Type check\n  if (actualType !== schema.type) {\n    errors.push({\n      path,\n      message: `Type mismatch`,\n      expected: schema.type,\n      received: actualType,\n    });\n    return; // Early exit — no point validating constraints on wrong type\n  }\n\n  // Type-specific validation\n  switch (schema.type) {\n    case \"string\":\n      validateString(value as string, schema, path, errors);\n      break;\n    case \"number\":\n      validateNumber(value as number, schema, path, errors);\n      break;\n    case \"object\":\n      validateObject(value as Record<string, unknown>, schema, path, errors, stack);\n      break;\n    case \"array\":\n      validateArray(value as unknown[], schema, path, errors, stack);\n      break;\n    // boolean and null need no further validation\n  }\n}\n\nfunction getJsonType(value: unknown): JsonSchemaType {\n  if (value === null) return \"null\";\n  if (Array.isArray(value)) return \"array\";\n  const t = typeof value;\n  if (t === \"string\") return \"string\";\n  if (t === \"number\") return \"number\";\n  if (t === \"boolean\") return \"boolean\";\n  if (t === \"object\") return \"object\";\n  return \"string\"; // fallback\n}\n\nfunction validateString(\n  value: string,\n  schema: JsonSchema,\n  path: string,\n  errors: ValidationError[],\n): void {\n  if (schema.minLength !== undefined && value.length < schema.minLength) {\n    errors.push({\n      path,\n      message: `String too short`,\n      expected: `minLength ${schema.minLength}`,\n      received: `length ${value.length}`,\n    });\n  }\n  if (schema.maxLength !== undefined && value.length > schema.maxLength) {\n    errors.push({\n      path,\n      message: `String too long`,\n      expected: `maxLength ${schema.maxLength}`,\n      received: `length ${value.length}`,\n    });\n  }\n}\n\nfunction validateNumber(\n  value: number,\n  schema: JsonSchema,\n  path: string,\n  errors: ValidationError[],\n): void {\n  if (schema.minimum !== undefined && value < schema.minimum) {\n    errors.push({\n      path,\n      message: `Number below minimum`,\n      expected: `>= ${schema.minimum}`,\n      received: `${value}`,\n    });\n  }\n  if (schema.maximum !== undefined && value > schema.maximum) {\n    errors.push({\n      path,\n      message: `Number above maximum`,\n      expected: `<= ${schema.maximum}`,\n      received: `${value}`,\n    });\n  }\n}\n\nfunction validateObject(\n  value: Record<string, unknown>,\n  schema: JsonSchema,\n  path: string,\n  errors: ValidationError[],\n  stack: Array<{ value: unknown; schema: JsonSchema; path: string }>,\n): void {\n  // Check required fields\n  if (schema.required) {\n    for (let i = 0; i < schema.required.length; i++) {\n      const key = schema.required[i];\n      if (!(key in value)) {\n        errors.push({\n          path: `${path}.${key}`,\n          message: `Missing required property`,\n          expected: `property \"${key}\"`,\n          received: \"undefined\",\n        });\n      }\n    }\n  }\n\n  // Validate properties — push onto stack for iterative processing\n  if (schema.properties) {\n    const keys = Object.keys(schema.properties);\n    for (let i = 0; i < keys.length; i++) {\n      const key = keys[i];\n      if (key in value) {\n        stack.push({\n          value: value[key],\n          schema: schema.properties[key],\n          path: `${path}.${key}`,\n        });\n      }\n    }\n  }\n}\n\nfunction validateArray(\n  value: unknown[],\n  schema: JsonSchema,\n  path: string,\n  errors: ValidationError[],\n  stack: Array<{ value: unknown; schema: JsonSchema; path: string }>,\n): void {\n  if (schema.minItems !== undefined && value.length < schema.minItems) {\n    errors.push({\n      path,\n      message: `Array too short`,\n      expected: `minItems ${schema.minItems}`,\n      received: `${value.length} items`,\n    });\n  }\n  if (schema.maxItems !== undefined && value.length > schema.maxItems) {\n    errors.push({\n      path,\n      message: `Array too long`,\n      expected: `maxItems ${schema.maxItems}`,\n      received: `${value.length} items`,\n    });\n  }\n\n  // Validate items — push onto stack for iterative processing\n  if (schema.items) {\n    for (let i = 0; i < value.length; i++) {\n      stack.push({\n        value: value[i],\n        schema: schema.items,\n        path: `${path}[${i}]`,\n      });\n    }\n  }\n}\n\n// ─── CLI Entry Point ─────────────────────────────────────────────────────────\n\nif (import.meta.main) {\n  const input = process.argv[2];\n  if (!input) {\n    console.log(\"Usage: bun run src/json-validator.ts '<json-string>'\");\n    console.log(\"       bun run src/json-validator.ts --benchmark\");\n    process.exit(1);\n  }\n\n  if (input === \"--benchmark\") {\n    // Quick benchmark: validate a moderately complex JSON 100k times\n    const testData = JSON.stringify({\n      name: \"test\",\n      age: 30,\n      active: true,\n      tags: [\"a\", \"b\", \"c\"],\n      address: { street: \"123 Main\", city: \"Springfield\", zip: \"12345\" },\n    });\n    const schema: JsonSchema = {\n      type: \"object\",\n      required: [\"name\", \"age\"],\n      properties: {\n        name: { type: \"string\", minLength: 1 },\n        age: { type: \"number\", minimum: 0 },\n        active: { type: \"boolean\" },\n        tags: { type: \"array\", items: { type: \"string\" } },\n        address: {\n          type: \"object\",\n          properties: {\n            street: { type: \"string\" },\n            city: { type: \"string\" },\n            zip: { type: \"string\" },\n          },\n        },\n      },\n    };\n\n    const iterations = 100_000;\n    const start = performance.now();\n    for (let i = 0; i < iterations; i++) {\n      validateJson(testData, schema);\n    }\n    const elapsed = performance.now() - start;\n\n    console.log(`Benchmark: ${iterations.toLocaleString()} validations`);\n    console.log(`Total: ${elapsed.toFixed(2)}ms`);\n    console.log(`Per validation: ${(elapsed / iterations).toFixed(4)}ms`);\n    console.log(`Ops/sec: ${((iterations / elapsed) * 1000).toFixed(0)}`);\n  } else {\n    const valid = isValidJson(input);\n    console.log(`Valid JSON: ${valid}`);\n    if (valid) {\n      const result = parseJsonSafe(input);\n      console.log(\"Parsed:\", JSON.stringify(result.data, null, 2));\n    }\n  }\n}\n"
