        "file_path": "/private/tmp/rp1-evals/98ce475e/workspace/src/json-validator.test.ts",
        "content": "import { describe, expect, test } from \"bun:test\";\nimport {\n  isValidJson,\n  parseJsonSafe,\n  validateJson,\n  type JsonSchema,\n  type ValidationResult,\n} from \"./json-validator\";\n\n// ─── isValidJson ─────────────────────────────────────────────────────────────\n\ndescribe(\"isValidJson\", () => {\n  test(\"returns true for valid JSON objects\", () => {\n    expect(isValidJson('{\"key\": \"value\"}')).toBe(true);\n    expect(isValidJson(\"{}\")).toBe(true);\n  });\n\n  test(\"returns true for valid JSON arrays\", () => {\n    expect(isValidJson(\"[1, 2, 3]\")).toBe(true);\n    expect(isValidJson(\"[]\")).toBe(true);\n  });\n\n  test(\"returns true for valid JSON primitives\", () => {\n    expect(isValidJson('\"hello\"')).toBe(true);\n    expect(isValidJson(\"42\")).toBe(true);\n    expect(isValidJson(\"true\")).toBe(true);\n    expect(isValidJson(\"false\")).toBe(true);\n    expect(isValidJson(\"null\")).toBe(true);\n    expect(isValidJson(\"-3.14\")).toBe(true);\n  });\n\n  test(\"returns false for empty string\", () => {\n    expect(isValidJson(\"\")).toBe(false);\n  });\n\n  test(\"returns false for invalid JSON\", () => {\n    expect(isValidJson(\"{key: value}\")).toBe(false);\n    expect(isValidJson(\"undefined\")).toBe(false);\n    expect(isValidJson(\"{trailing,}\")).toBe(false);\n    expect(isValidJson(\"'single quotes'\")).toBe(false);\n  });\n\n  test(\"returns false for non-JSON starting characters\", () => {\n    expect(isValidJson(\"hello\")).toBe(false);\n    expect(isValidJson(\"@invalid\")).toBe(false);\n  });\n});\n\n// ─── parseJsonSafe ───────────────────────────────────────────────────────────\n\ndescribe(\"parseJsonSafe\", () => {\n  test(\"parses valid JSON successfully\", () => {\n    const result = parseJsonSafe<{ name: string }>('{\"name\": \"Alice\"}');\n    expect(result.success).toBe(true);\n    expect(result.data).toEqual({ name: \"Alice\" });\n    expect(result.error).toBeUndefined();\n  });\n\n  test(\"parses arrays\", () => {\n    const result = parseJsonSafe<number[]>(\"[1, 2, 3]\");\n    expect(result.success).toBe(true);\n    expect(result.data).toEqual([1, 2, 3]);\n  });\n\n  test(\"parses primitives\", () => {\n    expect(parseJsonSafe(\"42\").data).toBe(42);\n    expect(parseJsonSafe('\"hello\"').data).toBe(\"hello\");\n    expect(parseJsonSafe(\"true\").data).toBe(true);\n    expect(parseJsonSafe(\"null\").data).toBeNull();\n  });\n\n  test(\"returns error for empty input\", () => {\n    const result = parseJsonSafe(\"\");\n    expect(result.success).toBe(false);\n    expect(result.error).toBe(\"Empty input\");\n    expect(result.data).toBeUndefined();\n  });\n\n  test(\"returns error for invalid JSON\", () => {\n    const result = parseJsonSafe(\"{invalid}\");\n    expect(result.success).toBe(false);\n    expect(result.error).toBeDefined();\n    expect(result.data).toBeUndefined();\n  });\n\n  test(\"handles deeply nested structures\", () => {\n    const deep = '{\"a\":{\"b\":{\"c\":{\"d\":{\"e\":\"deep\"}}}}}';\n    const result = parseJsonSafe(deep);\n    expect(result.success).toBe(true);\n  });\n});\n\n// ─── validateJson ────────────────────────────────────────────────────────────\n\ndescribe(\"validateJson\", () => {\n  describe(\"type validation\", () => {\n    test(\"validates string type\", () => {\n      const schema: JsonSchema = { type: \"string\" };\n      expect(validateJson('\"hello\"', schema).success).toBe(true);\n      expect(validateJson(\"42\", schema).success).toBe(false);\n    });\n\n    test(\"validates number type\", () => {\n      const schema: JsonSchema = { type: \"number\" };\n      expect(validateJson(\"42\", schema).success).toBe(true);\n      expect(validateJson(\"-3.14\", schema).success).toBe(true);\n      expect(validateJson('\"not a number\"', schema).success).toBe(false);\n    });\n\n    test(\"validates boolean type\", () => {\n      const schema: JsonSchema = { type: \"boolean\" };\n      expect(validateJson(\"true\", schema).success).toBe(true);\n      expect(validateJson(\"false\", schema).success).toBe(true);\n      expect(validateJson(\"1\", schema).success).toBe(false);\n    });\n\n    test(\"validates null type\", () => {\n      const schema: JsonSchema = { type: \"null\" };\n      expect(validateJson(\"null\", schema).success).toBe(true);\n      expect(validateJson('\"null\"', schema).success).toBe(false);\n    });\n\n    test(\"validates array type\", () => {\n      const schema: JsonSchema = { type: \"array\" };\n      expect(validateJson(\"[]\", schema).success).toBe(true);\n      expect(validateJson(\"[1, 2, 3]\", schema).success).toBe(true);\n      expect(validateJson(\"{}\", schema).success).toBe(false);\n    });\n\n    test(\"validates object type\", () => {\n      const schema: JsonSchema = { type: \"object\" };\n      expect(validateJson(\"{}\", schema).success).toBe(true);\n      expect(validateJson(\"[]\", schema).success).toBe(false);\n    });\n  });\n\n  describe(\"string constraints\", () => {\n    test(\"validates minLength\", () => {\n      const schema: JsonSchema = { type: \"string\", minLength: 3 };\n      expect(validateJson('\"abc\"', schema).success).toBe(true);\n      expect(validateJson('\"ab\"', schema).success).toBe(false);\n    });\n\n    test(\"validates maxLength\", () => {\n      const schema: JsonSchema = { type: \"string\", maxLength: 5 };\n      expect(validateJson('\"hello\"', schema).success).toBe(true);\n      expect(validateJson('\"toolong\"', schema).success).toBe(false);\n    });\n  });\n\n  describe(\"number constraints\", () => {\n    test(\"validates minimum\", () => {\n      const schema: JsonSchema = { type: \"number\", minimum: 0 };\n      expect(validateJson(\"5\", schema).success).toBe(true);\n      expect(validateJson(\"0\", schema).success).toBe(true);\n      expect(validateJson(\"-1\", schema).success).toBe(false);\n    });\n\n    test(\"validates maximum\", () => {\n      const schema: JsonSchema = { type: \"number\", maximum: 100 };\n      expect(validateJson(\"50\", schema).success).toBe(true);\n      expect(validateJson(\"100\", schema).success).toBe(true);\n      expect(validateJson(\"101\", schema).success).toBe(false);\n    });\n  });\n\n  describe(\"array constraints\", () => {\n    test(\"validates minItems\", () => {\n      const schema: JsonSchema = { type: \"array\", minItems: 2 };\n      expect(validateJson(\"[1, 2]\", schema).success).toBe(true);\n      expect(validateJson(\"[1]\", schema).success).toBe(false);\n    });\n\n    test(\"validates maxItems\", () => {\n      const schema: JsonSchema = { type: \"array\", maxItems: 3 };\n      expect(validateJson(\"[1, 2, 3]\", schema).success).toBe(true);\n      expect(validateJson(\"[1, 2, 3, 4]\", schema).success).toBe(false);\n    });\n\n    test(\"validates array items schema\", () => {\n      const schema: JsonSchema = {\n        type: \"array\",\n        items: { type: \"number\" },\n      };\n      expect(validateJson(\"[1, 2, 3]\", schema).success).toBe(true);\n\n      const result = validateJson('[1, \"two\", 3]', schema);\n      expect(result.success).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n    });\n  });\n\n  describe(\"object validation\", () => {\n    test(\"validates required properties\", () => {\n      const schema: JsonSchema = {\n        type: \"object\",\n        required: [\"name\", \"age\"],\n        properties: {\n          name: { type: \"string\" },\n          age: { type: \"number\" },\n        },\n      };\n\n      expect(validateJson('{\"name\": \"Alice\", \"age\": 30}', schema).success).toBe(true);\n\n      const result = validateJson('{\"name\": \"Alice\"}', schema);\n      expect(result.success).toBe(false);\n      expect(result.errors.some((e) => e.path === \"$.age\")).toBe(true);\n    });\n\n    test(\"validates property types\", () => {\n      const schema: JsonSchema = {\n        type: \"object\",\n        properties: {\n          name: { type: \"string\" },\n          age: { type: \"number\" },\n        },\n      };\n\n      const result = validateJson('{\"name\": 42, \"age\": \"old\"}', schema);\n      expect(result.success).toBe(false);\n      expect(result.errors.length).toBe(2);\n    });\n\n    test(\"allows extra properties not in schema\", () => {\n      const schema: JsonSchema = {\n        type: \"object\",\n        properties: {\n          name: { type: \"string\" },\n        },\n      };\n\n      expect(validateJson('{\"name\": \"Alice\", \"extra\": true}', schema).success).toBe(true);\n    });\n  });\n\n  describe(\"nested object validation\", () => {\n    test(\"validates deeply nested objects\", () => {\n      const schema: JsonSchema = {\n        type: \"object\",\n        properties: {\n          user: {\n            type: \"object\",\n            required: [\"name\"],\n            properties: {\n              name: { type: \"string\" },\n              address: {\n                type: \"object\",\n                properties: {\n                  city: { type: \"string\" },\n                  zip: { type: \"string\", minLength: 5 },\n                },\n              },\n            },\n          },\n        },\n      };\n\n      const valid = validateJson(\n        '{\"user\": {\"name\": \"Alice\", \"address\": {\"city\": \"NYC\", \"zip\": \"10001\"}}}',\n        schema,\n      );\n      expect(valid.success).toBe(true);\n\n      const invalid = validateJson(\n        '{\"user\": {\"name\": \"Alice\", \"address\": {\"city\": \"NYC\", \"zip\": \"123\"}}}',\n        schema,\n      );\n      expect(invalid.success).toBe(false);\n      expect(invalid.errors[0].path).toBe(\"$.user.address.zip\");\n    });\n  });\n\n  describe(\"nullable values\", () => {\n    test(\"allows null when nullable is true\", () => {\n      const schema: JsonSchema = { type: \"string\", nullable: true };\n      expect(validateJson(\"null\", schema).success).toBe(true);\n    });\n\n    test(\"rejects null when nullable is false\", () => 