        '{"user": {"name": "Alice", "address": {"city": "NYC", "zip": "123"}}}',
        schema,
      );
      expect(invalid.success).toBe(false);
      expect(invalid.errors[0].path).toBe("$.user.address.zip");
    });
  });

  describe("nullable values", () => {
    test("allows null when nullable is true", () => {
      const schema: JsonSchema = { type: "string", nullable: true };
      expect(validateJson("null", schema).success).toBe(true);
    });

    test("rejects null when nullable is false", () => {
      const schema: JsonSchema = { type: "string" };
      expect(validateJson("null", schema).success).toBe(false);
    });
  });

  describe("error reporting", () => {
    test("includes path in error messages", () => {
      const schema: JsonSchema = {
        type: "object",
        properties: {
          items: {
            type: "array",
            items: { type: "number" },
          },
        },
      };

      const result = validateJson('{"items": [1, "bad", 3]}', schema);
      expect(result.success).toBe(false);
      expect(result.errors[0].path).toBe("$.items[1]");
    });

    test("returns invalid JSON error for malformed input", () => {
      const schema: JsonSchema = { type: "object" };
      const result = validateJson("{bad json}", schema);
      expect(result.success).toBe(false);
      expect(result.errors[0].path).toBe("$");
      expect(result.errors[0].message).toBe("Invalid JSON");
    });
  });

  describe("performance", () => {
    test("validates large arrays quickly", () => {
      const largeArray = JSON.stringify(Array.from({ length: 10_000 }, (_, i) => i));
      const schema: JsonSchema = { type: "array", items: { type: "number" } };

      const start = performance.now();
      const result = validateJson(largeArray, schema);
      const elapsed = performance.now() - start;

      expect(result.success).toBe(true);
      // Should validate 10k items in under 100ms
      expect(elapsed).toBeLessThan(100);
    });

    test("validates large objects quickly", () => {
      const obj: Record<string, unknown> = {};
      const properties: Record<string, JsonSchema> = {};
      for (let i = 0; i < 1_000; i++) {
        obj[`key${i}`] = `value${i}`;
        properties[`key${i}`] = { type: "string" };
      }

      const schema: JsonSchema = { type: "object", properties };

      const start = performance.now();
      const result = validateJson(JSON.stringify(obj), schema);
      const elapsed = performance.now() - start;

      expect(result.success).toBe(true);
      // Should validate 1k properties in under 50ms
      expect(elapsed).toBeLessThan(50);
    });
  });
