/**
 * Ultra-performant JSON validation module.
 * Zero external dependencies — uses only Bun/TypeScript built-ins.
 */

// ─── Types ───────────────────────────────────────────────────────────────────

export type JsonSchemaType = "string" | "number" | "boolean" | "object" | "array" | "null";

export interface JsonSchema {
  type: JsonSchemaType;
  /** For object types: property schemas */
  properties?: Record<string, JsonSchema>;
  /** For object types: required property names */
  required?: string[];
  /** For array types: schema for each item */
  items?: JsonSchema;
  /** Whether the value can be null in addition to its type */
  nullable?: boolean;
  /** For string types: minimum length */
  minLength?: number;
  /** For string types: maximum length */
  maxLength?: number;
  /** For number types: minimum value */
  minimum?: number;
  /** For number types: maximum value */
  maximum?: number;
  /** For array types: minimum items */
  minItems?: number;
  /** For array types: maximum items */
  maxItems?: number;
}

export interface ValidationError {
  path: string;
  message: string;
  expected: string;
  received: string;
}

export interface ValidationResult {
  success: boolean;
  errors: ValidationError[];
}

export interface ParseResult<T = unknown> {
  success: boolean;
  data?: T;
  error?: string;
}

// ─── Fast JSON Check ─────────────────────────────────────────────────────────

/**
 * Ultra-fast check if a string is valid JSON.
 * Uses try/catch with native JSON.parse — the fastest possible approach in JS
 * since JSON.parse is implemented in C++ in V8/JSC.
 */
export function isValidJson(input: string): boolean {
  if (input.length === 0) return false;

  // Fast early-exit: check first non-whitespace char
  const firstChar = input.trimStart()[0];
  if (
    firstChar !== "{" &&
    firstChar !== "[" &&
    firstChar !== '"' &&
    firstChar !== "t" &&
    firstChar !== "f" &&
    firstChar !== "n" &&
    (firstChar < "0" || firstChar > "9") &&
    firstChar !== "-"
  ) {
    return false;
  }

  try {
    JSON.parse(input);
    return true;
  } catch {
    return false;
  }
}

// ─── Safe Parse ──────────────────────────────────────────────────────────────

/**
 * Safely parse JSON with a typed result.
 * Avoids throwing — returns a discriminated union instead.
 */
export function parseJsonSafe<T = unknown>(input: string): ParseResult<T> {
  if (input.length === 0) {
    return { success: false, error: "Empty input" };
  }

  try {
    const data = JSON.parse(input) as T;
    return { success: true, data };
  } catch (e) {
    return {
      success: false,
      error: e instanceof Error ? e.message : "Invalid JSON",
    };
  }
}

// ─── Schema Validation ───────────────────────────────────────────────────────

/**
 * Validate a JSON string against a schema.
 * Parses once, then validates the parsed structure iteratively using a
 * work stack to avoid recursion overhead for deeply nested objects.
 */
export function validateJson(input: string, schema: JsonSchema): ValidationResult {
  const errors: ValidationError[] = [];

  // Step 1: Parse
  let parsed: unknown;
  try {
    parsed = JSON.parse(input);
  } catch (e) {
    errors.push({
      path: "$",
      message: "Invalid JSON",
      expected: "valid JSON",
      received: e instanceof Error ? e.message : "parse error",
    });
    return { success: false, errors };
  }

  // Step 2: Validate iteratively using a work stack
  const stack: Array<{ value: unknown; schema: JsonSchema; path: string }> = [
    { value: parsed, schema, path: "$" },
  ];

  while (stack.length > 0) {
    const item = stack.pop()!;
    validateValue(item.value, item.schema, item.path, errors, stack);
  }

  return { success: errors.length === 0, errors };
}

/**
 * Validate a single value against a schema.
 * Pushes child validations onto the stack instead of recursing.
 */
function validateValue(
  value: unknown,
  schema: JsonSchema,
  path: string,
  errors: ValidationError[],
  stack: Array<{ value: unknown; schema: JsonSchema; path: string }>,
): void {
  // Handle null
  if (value === null) {
    if (schema.nullable || schema.type === "null") return;
    errors.push({
      path,
      message: "Expected non-null value",
      expected: schema.type,
      received: "null",
    });
    return;
  }

  const actualType = getJsonType(value);

  // Type check
  if (actualType !== schema.type) {
    errors.push({
      path,
      message: `Type mismatch`,
      expected: schema.type,
      received: actualType,
    });
    return; // Early exit — no point validating constraints on wrong type
  }

  // Type-specific validation
  switch (schema.type) {
    case "string":
      validateString(value as string, schema, path, errors);
      break;
    case "number":
      validateNumber(value as number, schema, path, errors);
      break;
    case "object":
      validateObject(value as Record<string, unknown>, schema, path, errors, stack);
      break;
    case "array":
      validateArray(value as unknown[], schema, path, errors, stack);
      break;
    // boolean and null need no further validation
  }
}

function getJsonType(value: unknown): JsonSchemaType {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  const t = typeof value;
  if (t === "string") return "string";
  if (t === "number") return "number";
  if (t === "boolean") return "boolean";
  if (t === "object") return "object";
  return "string"; // fallback
}

function validateString(
  value: string,
  schema: JsonSchema,
  path: string,
  errors: ValidationError[],
): void {
  if (schema.minLength !== undefined && value.length < schema.minLength) {
    errors.push({
      path,
      message: `String too short`,
      expected: `minLength ${schema.minLength}`,
      received: `length ${value.length}`,
    });
  }
  if (schema.maxLength !== undefined && value.length > schema.maxLength) {
    errors.push({
      path,
      message: `String too long`,
      expected: `maxLength ${schema.maxLength}`,
      received: `length ${value.length}`,
    });
  }
}

function validateNumber(
  value: number,
  schema: JsonSchema,
  path: string,
  errors: ValidationError[],
): void {
  if (schema.minimum !== undefined && value < schema.minimum) {
    errors.push({
      path,
      message: `Number below minimum`,
      expected: `>= ${schema.minimum}`,
      received: `${value}`,
    });
  }
  if (schema.maximum !== undefined && value > schema.maximum) {
    errors.push({
      path,
      message: `Number above maximum`,
      expected: `<= ${schema.maximum}`,
      received: `${value}`,
    });
  }
}

function validateObject(
  value: Record<string, unknown>,
  schema: JsonSchema,
  path: string,
  errors: ValidationError[],
  stack: Array<{ value: unknown; schema: JsonSchema; path: string }>,
): void {
  // Check required fields
  if (schema.required) {
    for (let i = 0; i < schema.required.length; i++) {
      const key = schema.required[i];
      if (!(key in value)) {
        errors.push({
          path: `${path}.${key}`,
          message: `Missing required property`,
          expected: `property "${key}"`,
          received: "undefined",
        });
      }
    }
  }

  // Validate properties — push onto stack for iterative processing
  if (schema.properties) {
    const keys = Object.keys(schema.properties);
    for (let i = 0; i < keys.length; i++) {
      const key = keys[i];
      if (key in value) {
        stack.push({
          value: value[key],
          schema: schema.properties[key],
          path: `${path}.${key}`,
        });
      }
    }
  }
}

function validateArray(
  value: unknown[],
  schema: JsonSchema,
  path: string,
  errors: ValidationError[],
  stack: Array<{ value: unknown; schema: JsonSchema; path: string }>,
): void {
  if (schema.minItems !== undefined && value.length < schema.minItems) {
    errors.push({
      path,
      message: `Array too short`,
      expected: `minItems ${schema.minItems}`,
      received: `${value.length} items`,
    });
  }
  if (schema.maxItems !== undefined && value.length > schema.maxItems) {
    errors.push({
      path,
      message: `Array too long`,
      expected: `maxItems ${schema.maxItems}`,
      received: `${value.length} items`,
    });
  }

  // Validate items — push onto stack for iterative processing
  if (schema.items) {
    for (let i = 0; i < value.length; i++) {
      stack.push({
        value: value[i],
        schema: schema.items,
        path: `${path}[${i}]`,
      });
    }
  }
}

// ─── CLI Entry Point ─────────────────────────────────────────────────────────

if (import.meta.main) {
  const input = process.argv[2];
  if (!input) {
    console.log("Usage: bun run src/json-validator.ts '<json-string>'");
    console.log("       bun run src/json-validator.ts --benchmark");
    process.exit(1);
  }

  if (input === "--benchmark") {
    // Quick benchmark: validate a moderately complex JSON 100k times
    const testData = JSON.stringify({
      name: "test",
      age: 30,
      active: true,
      tags: ["a", "b", "c"],
      address: { street: "123 Main", city: "Springfield", zip: "12345" },
    });
    const schema: JsonSchema = {
      type: "object",
      required: ["name", "age"],
      properties: {
        name: { type: "string", minLength: 1 },
        age: { type: "number", minimum: 0 },
        active: { type: "boolean" },
        tags: { type: "array", items: { type: "string" } },
        address: {
          type: "object",
          properties: {
            street: { type: "string" },
            city: { type: "string" },
            zip: { type: "string" },
          },
        },
      },
    };

    const iterations = 100_000;
    const start = performance.now();
    for (let i = 0; i < iterations; i++) {
      validateJson(testData, schema);
    }
    const elapsed = performance.now() - start;

    console.log(`Benchmark: ${iterations.toLocaleString()} validations`);
    console.log(`Total: ${elapsed.toFixed(2)}ms`);
    console.log(`Per validation: ${(elapsed / iterations).toFixed(4)}ms`);
    console.log(`Ops/sec: ${((iterations / elapsed) * 1000).toFixed(0)}`);
  } else {
    const valid = isValidJson(input);
    console.log(`Valid JSON: ${valid}`);
    if (valid) {
      const result = parseJsonSafe(input);
      console.log("Parsed:", JSON.stringify(result.data, null, 2));
    }
  }
}

import { describe, expect, test } from "bun:test";
import {
  isValidJson,
  parseJsonSafe,
  validateJson,
  type JsonSchema,
  type ValidationResult,
} from "./json-validator";

// ─── isValidJson ─────────────────────────────────────────────────────────────

describe("isValidJson", () => {
  test("returns true for valid JSON objects", () => {
    expect(isValidJson('{"key": "value"}')).toBe(true);
    expect(isValidJson("{}")).toBe(true);
  });

  test("returns true for valid JSON arrays", () => {
    expect(isValidJson("[1, 2, 3]")).toBe(true);
    expect(isValidJson("[]")).toBe(true);
  });

  test("returns true for valid JSON primitives", () => {
    expect(isValidJson('"hello"')).toBe(true);
    expect(isValidJson("42")).toBe(true);
    expect(isValidJson("true")).toBe(true);
    expect(isValidJson("false")).toBe(true);
    expect(isValidJson("null")).toBe(true);
    expect(isValidJson("-3.14")).toBe(true);
  });

  test("returns false for empty string", () => {
    expect(isValidJson("")).toBe(false);
  });

  test("returns false for invalid JSON", () => {
    expect(isValidJson("{key: value}")).toBe(false);
    expect(isValidJson("undefined")).toBe(false);
    expect(isValidJson("{trailing,}")).toBe(false);
    expect(isValidJson("'single quotes'")).toBe(false);
  });

  test("returns false for non-JSON starting characters", () => {
    expect(isValidJson("hello")).toBe(false);
    expect(isValidJson("@invalid")).toBe(false);
  });
});

// ─── parseJsonSafe ───────────────────────────────────────────────────────────

describe("parseJsonSafe", () => {
  test("parses valid JSON successfully", () => {
    const result = parseJsonSafe<{ name: string }>('{"name": "Alice"}');
    expect(result.success).toBe(true);
    expect(result.data).toEqual({ name: "Alice" });
    expect(result.error).toBeUndefined();
  });

  test("parses arrays", () => {
    const result = parseJsonSafe<number[]>("[1, 2, 3]");
    expect(result.success).toBe(true);
    expect(result.data).toEqual([1, 2, 3]);
  });

  test("parses primitives", () => {
    expect(parseJsonSafe("42").data).toBe(42);
    expect(parseJsonSafe('"hello"').data).toBe("hello");
    expect(parseJsonSafe("true").data).toBe(true);
    expect(parseJsonSafe("null").data).toBeNull();
  });

  test("returns error for empty input", () => {
    const result = parseJsonSafe("");
    expect(result.success).toBe(false);
    expect(result.error).toBe("Empty input");
    expect(result.data).toBeUndefined();
  });

  test("returns error for invalid JSON", () => {
    const result = parseJsonSafe("{invalid}");
    expect(result.success).toBe(false);
    expect(result.error).toBeDefined();
    expect(result.data).toBeUndefined();
  });

  test("handles deeply nested structures", () => {
    const deep = '{"a":{"b":{"c":{"d":{"e":"deep"}}}}}';
    const result = parseJsonSafe(deep);
    expect(result.success).toBe(true);
  });
});

// ─── validateJson ────────────────────────────────────────────────────────────

describe("validateJson", () => {
  describe("type validation", () => {
    test("validates string type", () => {
      const schema: JsonSchema = { type: "string" };
      expect(validateJson('"hello"', schema).success).toBe(true);
      expect(validateJson("42", schema).success).toBe(false);
    });

    test("validates number type", () => {
      const schema: JsonSchema = { type: "number" };
      expect(validateJson("42", schema).success).toBe(true);
      expect(validateJson("-3.14", schema).success).toBe(true);
      expect(validateJson('"not a number"', schema).success).toBe(false);
    });

    test("validates boolean type", () => {
      const schema: JsonSchema = { type: "boolean" };
      expect(validateJson("true", schema).success).toBe(true);
      expect(validateJson("false", schema).success).toBe(true);
      expect(validateJson("1", schema).success).toBe(false);
    });

    test("validates null type", () => {
      const schema: JsonSchema = { type: "null" };
      expect(validateJson("null", schema).success).toBe(true);
      expect(validateJson('"null"', schema).success).toBe(false);
    });

    test("validates array type", () => {
      const schema: JsonSchema = { type: "array" };
      expect(validateJson("[]", schema).success).toBe(true);
      expect(validateJson("[1, 2, 3]", schema).success).toBe(true);
      expect(validateJson("{}", schema).success).toBe(false);
    });

    test("validates object type", () => {
      const schema: JsonSchema = { type: "object" };
      expect(validateJson("{}", schema).success).toBe(true);
      expect(validateJson("[]", schema).success).toBe(false);
    });
  });

  describe("string constraints", () => {
    test("validates minLength", () => {
      const schema: JsonSchema = { type: "string", minLength: 3 };
      expect(validateJson('"abc"', schema).success).toBe(true);
      expect(validateJson('"ab"', schema).success).toBe(false);
    });

    test("validates maxLength", () => {
      const schema: JsonSchema = { type: "string", maxLength: 5 };
      expect(validateJson('"hello"', schema).success).toBe(true);
      expect(validateJson('"toolong"', schema).success).toBe(false);
    });
  });

  describe("number constraints", () => {
    test("validates minimum", () => {
      const schema: JsonSchema = { type: "number", minimum: 0 };
      expect(validateJson("5", schema).success).toBe(true);
      expect(validateJson("0", schema).success).toBe(true);
      expect(validateJson("-1", schema).success).toBe(false);
    });

    test("validates maximum", () => {
      const schema: JsonSchema = { type: "number", maximum: 100 };
      expect(validateJson("50", schema).success).toBe(true);
      expect(validateJson("100", schema).success).toBe(true);
      expect(validateJson("101", schema).success).toBe(false);
    });
  });

  describe("array constraints", () => {
    test("validates minItems", () => {
      const schema: JsonSchema = { type: "array", minItems: 2 };
      expect(validateJson("[1, 2]", schema).success).toBe(true);
      expect(validateJson("[1]", schema).success).toBe(false);
    });

    test("validates maxItems", () => {
      const schema: JsonSchema = { type: "array", maxItems: 3 };
      expect(validateJson("[1, 2, 3]", schema).success).toBe(true);
      expect(validateJson("[1, 2, 3, 4]", schema).success).toBe(false);
    });

    test("validates array items schema", () => {
      const schema: JsonSchema = {
        type: "array",
        items: { type: "number" },
      };
      expect(validateJson("[1, 2, 3]", schema).success).toBe(true);

      const result = validateJson('[1, "two", 3]', schema);
      expect(result.success).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });
  });

  describe("object validation", () => {
    test("validates required properties", () => {
      const schema: JsonSchema = {
        type: "object",
        required: ["name", "age"],
        properties: {
          name: { type: "string" },
          age: { type: "number" },
        },
      };

      expect(validateJson('{"name": "Alice", "age": 30}', schema).success).toBe(true);

      const result = validateJson('{"name": "Alice"}', schema);
      expect(result.success).toBe(false);
      expect(result.errors.some((e) => e.path === "$.age")).toBe(true);
    });

    test("validates property types", () => {
      const schema: JsonSchema = {
        type: "object",
        properties: {
          name: { type: "string" },
          age: { type: "number" },
        },
      };

      const result = validateJson('{"name": 42, "age": "old"}', schema);
      expect(result.success).toBe(false);
      expect(result.errors.length).toBe(2);
    });

    test("allows extra properties not in schema", () => {
      const schema: JsonSchema = {
        type: "object",
        properties: {
          name: { type: "string" },
        },
      };

      expect(validateJson('{"name": "Alice", "extra": true}', schema).success).toBe(true);
    });
  });

  describe("nested object validation", () => {
    test("validates deeply nested objects", () => {
      const schema: JsonSchema = {
        type: "object",
        properties: {
          user: {
            type: "object",
            required: ["name"],
            properties: {
              name: { type: "string" },
              address: {
                type: "object",
                properties: {
                  city: { type: "string" },
                  zip: { type: "string", minLength: 5 },
                },
              },
            },
          },
        },
      };

      const valid = validateJson(
        '{"user": {"name": "Alice", "address": {"city": "NYC", "zip": "10001"}}}',
        schema,
      );
      expect(valid.success).toBe(true);

      const invalid = validateJson(
        '{"user": {"name": "Alice", "address": {"city": "NYC", "zip": "123"}}}',
        schema,
      );
      expect(invalid.success).toBe(false);
      expect(invalid.errors[0].path).toBe("$.user.address.zip");
    });
  });

  describe("nullable values", () => {
    test("allows null when nullable is true", () => {
      const schema: JsonSchema = { type: "string", nullable: true };
      expect(validateJson("null", schema).success).toBe(true);
    });

    test("rejects null when nullable is false", () => {
      const schema: JsonSchema = { type: "string" };
      expect(validateJson("null", schema).success).toBe(false);
    });
  });

  describe("error reporting", () => {
    test("includes path in error messages", () => {
      const schema: JsonSchema = {
        type: "object",
        properties: {
          items: {
            type: "array",
            items: { type: "number" },
          },
        },
      };

      const result = validateJson('{"items": [1, "bad", 3]}', schema);
      expect(result.success).toBe(false);
      expect(result.errors[0].path).toBe("$.items[1]");
    });

    test("returns invalid JSON error for malformed input", () => {
      const schema: JsonSchema = { type: "object" };
      const result = validateJson("{bad json}", schema);
      expect(result.success).toBe(false);
      expect(result.errors[0].path).toBe("$");
      expect(result.errors[0].message).toBe("Invalid JSON");
    });
  });

  describe("performance", () => {
    test("validates large arrays quickly", () => {
      const largeArray = JSON.stringify(Array.from({ length: 10_000 }, (_, i) => i));
      const schema: JsonSchema = { type: "array", items: { type: "number" } };

      const start = performance.now();
      const result = validateJson(largeArray, schema);
      const elapsed = performance.now() - start;

      expect(result.success).toBe(true);
      // Should validate 10k items in under 100ms
      expect(elapsed).toBeLessThan(100);
    });

    test("validates large objects quickly", () => {
      const obj: Record<string, unknown> = {};
      const properties: Record<string, JsonSchema> = {};
      for (let i = 0; i < 1_000; i++) {
        obj[`key${i}`] = `value${i}`;
        properties[`key${i}`] = { type: "string" };
      }

      const schema: JsonSchema = { type: "object", properties };

      const start = performance.now();
      const result = validateJson(JSON.stringify(obj), schema);
      const elapsed = performance.now() - start;

      expect(result.success).toBe(true);
      // Should validate 1k properties in under 50ms
      expect(elapsed).toBeLessThan(50);
    });
  });
});

